# Get help
I am trying to implement NumberField with the shadcn UI Form component but the form is not being submitted as it is triggering the internal number input for the NumberField

## Ask a question

```tsx
"use client"

import * as React from "react"
import * as LabelPrimitive from "@radix-ui/react-label"
import { Slot } from "@radix-ui/react-slot"
import {
  Controller,
  FormProvider,
  useFormContext,
  useFormState,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from "react-hook-form"

import { cn } from "@/lib/utils"
import { Label } from "@/components/ui/label"

const Form = FormProvider

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName
}

const FormFieldContext = React.createContext<FormFieldContextValue>(
  {} as FormFieldContextValue
)

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  )
}

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext)
  const itemContext = React.useContext(FormItemContext)
  const { getFieldState } = useFormContext()
  const formState = useFormState({ name: fieldContext.name })
  const fieldState = getFieldState(fieldContext.name, formState)

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>")
  }

  const { id } = itemContext

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  }
}

type FormItemContextValue = {
  id: string
}

const FormItemContext = React.createContext<FormItemContextValue>(
  {} as FormItemContextValue
)

function FormItem({ className, ...props }: React.ComponentProps<"div">) {
  const id = React.useId()

  return (
    <FormItemContext.Provider value={{ id }}>
      <div
        data-slot="form-item"
        className={cn("grid gap-2", className)}
        {...props}
      />
    </FormItemContext.Provider>
  )
}

function FormLabel({
  className,
  ...props
}: React.ComponentProps<typeof LabelPrimitive.Root>) {
  const { error, formItemId } = useFormField()

  return (
    <Label
      data-slot="form-label"
      data-error={!!error}
      className={cn("data-[error=true]:text-destructive", className)}
      htmlFor={formItemId}
      {...props}
    />
  )
}

function FormControl({ ...props }: React.ComponentProps<typeof Slot>) {
  const { error, formItemId, formDescriptionId, formMessageId } = useFormField()

  return (
    <Slot
      data-slot="form-control"
      id={formItemId}
      aria-describedby={
        !error
          ? `${formDescriptionId}`
          : `${formDescriptionId} ${formMessageId}`
      }
      aria-invalid={!!error}
      {...props}
    />
  )
}

function FormDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { formDescriptionId } = useFormField()

  return (
    <p
      data-slot="form-description"
      id={formDescriptionId}
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  )
}

function FormMessage({ className, ...props }: React.ComponentProps<"p">) {
  const { error, formMessageId } = useFormField()
  const body = error ? String(error?.message ?? "") : props.children

  if (!body) {
    return null
  }

  return (
    <p
      data-slot="form-message"
      id={formMessageId}
      className={cn("text-destructive text-sm", className)}
      {...props}
    >
      {body}
    </p>
  )
}

export {
  useFormField,
  Form,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  FormField,
}
```

```tsx
import { NumberField } from '@base-ui/react/number-field';
import { zodResolver } from '@hookform/resolvers/zod';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useLoaderData, useRouter } from '@tanstack/react-router';
import React from 'react';
import { useForm } from 'react-hook-form';
import { toast } from 'sonner';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import { DialogFooter } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { DotLoader } from '@/features/shared/components/dot-loader';
import { auth as authApi } from '@/lib/api';

// Validation schema for academic information
const academicInfoSchema = z.object({
  roll_no: z
    .string()
    .trim()
    .min(1, 'Roll number is required')
    .max(30, { message: 'Roll number must be at most 30 characters long' })
    .refine((v) => v.toString() !== '0', { message: 'Invalid roll number' }),
  branch: z.string().trim().min(1, 'Branch is required').max(25, { message: 'Branch must be at most 25 characters long' }),
  degree: z.string().trim().min(1, 'Degree is required').max(20, { message: 'Degree must be at most 20 characters long' }),
  graduation_year: z.number().min(2000, 'Year must be 2000 or later').max(2025, 'Year must be before 2025'),
  cgpa: z
    .number()
    .min(0, { message: 'CGPA must be between 0 and 10' })
    .max(10, { message: 'CGPA must be between 0 and 10' })
    .refine(
      (value) => {
        const hasDecimcalValues = Math.round(value * 100) <= value * 100;
        return hasDecimcalValues;
      },
      { message: 'CGPA must have at most 2 decimal places' },
    ),
  backlogs: z.number().min(0, 'Backlogs must be between 0 and 100').max(100, 'Backlogs must be between 0 and 100'),
});

type AcademicInfoFormValues = z.infer<typeof academicInfoSchema>;

interface StudentEditAcademicInfoFormProps {
  handleClose: () => void;
}

export function StudentEditAcademicInfoForm({ handleClose }: StudentEditAcademicInfoFormProps) {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { auth } = useLoaderData({ from: '/student/_authenticated' });

  const form = useForm<AcademicInfoFormValues>({
    resolver: zodResolver(academicInfoSchema),
    defaultValues: {
      roll_no: auth.roll_no,
      branch: auth.branch,
      degree: auth.degree,
      graduation_year: auth.graduation_year,
      cgpa: auth.cgpa,
      backlogs: auth.backlogs,
    },
  });

  const mutation = useMutation({
    mutationFn: authApi.studentUpdateUserDetails,
    onSuccess: (data) => {
      if (data.isErr()) {
        if (data.error.type === 'UNAUTHORIZED') {
          window.location.href = '/student/auth/login';
          return null;
        }
        let errorMessage: string;
        switch (data.error.type) {
          case 'FAILED_TO_FETCH':
            errorMessage = 'Failed to fetch';
            break;
          case 'INTERNAL_SERVER_ERROR':
            errorMessage = 'Internal server error!';
            break;
          case 'UNKNOWN_ERROR':
            errorMessage = 'Failed to update details!';
            break;
          case 'CLIENT_ERROR':
            errorMessage = data.error.error;
            break;
        }
        toast.error(errorMessage, { position: 'bottom-center' });
        return;
      }

      toast.success('Academic information updated successfully', { position: 'bottom-center' });
      queryClient.invalidateQueries({ queryKey: ['student', 'get-user-details'] });
      router.invalidate({ filter: (d) => d.routeId === '/student/_authenticated' });
      handleClose();
    },
    onError: (err) => {
      toast.error(err.message, { position: 'bottom-center' });
    },
  });

  const onSubmit = (data: AcademicInfoFormValues) => {
    mutation.mutate({ body: { ...data, cgpa: Number(data.cgpa) } });
  };

  // biome-ignore lint/correctness/useExhaustiveDependencies: No need to add the form.reset to the dependency array
  React.useEffect(() => {
    form.reset({
      roll_no: auth.roll_no,
      branch: auth.branch,
      degree: auth.degree,
      graduation_year: auth.graduation_year,
      cgpa: auth.cgpa,
      backlogs: auth.backlogs,
    });
  }, [auth.roll_no, auth.branch, auth.degree, auth.graduation_year, auth.cgpa, auth.backlogs]);

  return (
    <div>
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className='space-y-4 pt-2'>
          <div className='grid grid-cols-2 gap-4'>
            <FormField
              control={form.control}
              name='roll_no'
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Roll Number</FormLabel>
                  <FormControl>
                    <Input
                      placeholder='Enter roll number'
                      className='h-12 rounded-lg border-gray-200 bg-transparent px-4 text-base transition-all focus:border-primary focus:ring-1 focus:ring-primary'
                      autoComplete='off'
                      autoCapitalize='none'
                      autoCorrect='off'
                      spellCheck='false'
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name='graduation_year'
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Graduation Year</FormLabel>
                  <FormControl>
                    <Input
                      type='string'
                      placeholder='e.g., 2024'
                      inputMode='numeric'
                      className='h-12 rounded-lg border-gray-200 bg-transparent px-4 text-base transition-all focus:border-primary focus:ring-1 focus:ring-primary'
                      autoComplete='off'
                      autoCapitalize='none'
                      autoCorrect='off'
                      spellCheck='false'
                      {...field}
                      value={field.value}
                      onChange={(e) => field.onChange(Number.parseInt(e.target.value, 10) || 0)}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name='degree'
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Degree</FormLabel>
                  <FormControl>
                    <Input
                      placeholder='e.g., BE, BTech, MTech'
                      className='h-12 rounded-lg border-gray-200 bg-transparent px-4 text-base transition-all focus:border-primary focus:ring-1 focus:ring-primary'
                      autoComplete='off'
                      autoCapitalize='none'
                      autoCorrect='off'
                      spellCheck='false'
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name='branch'
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Branch</FormLabel>
                  <FormControl>
                    <Input
                      placeholder='e.g., CSE, ECE, ME'
                      className='h-12 rounded-lg border-gray-200 bg-transparent px-4 text-base transition-all focus:border-primary focus:ring-1 focus:ring-primary'
                      autoComplete='off'
                      autoCapitalize='none'
                      autoCorrect='off'
                      spellCheck='false'
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name='cgpa'
              render={({ field }) => (
                <FormItem>
                  <NumberField.Root
                    value={field.value}
                    min={0}
                    max={10}
                    step={0.01}
                    onValueChange={(value) => field.onChange(value)}
                    onValueCommitted={(value) => field.onChange(value)}
                  >
                    <FormLabel>CGPA</FormLabel>
                    <FormControl>
                      <NumberField.Input
                        ref={field.ref}
                        onBlur={field.onBlur}
                        render={
                          <Input
                            placeholder='Enter CGPA'
                            inputMode='decimal'
                            className='h-12 rounded-lg border-gray-200 bg-transparent px-4 text-base transition-all focus:border-primary focus:ring-1 focus:ring-primary'
                            autoComplete='off'
                            autoCapitalize='none'
                            autoCorrect='off'
                            spellCheck='false'
                          />
                        }
                      />
                    </FormControl>
                  </NumberField.Root>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name='backlogs'
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Backlogs</FormLabel>
                  <FormControl>
                    <Input
                      placeholder='Enter backlogs'
                      inputMode='numeric'
                      className='h-12 rounded-lg border-gray-200 bg-transparent px-4 text-base transition-all focus:border-primary focus:ring-1 focus:ring-primary'
                      autoComplete='off'
                      autoCapitalize='none'
                      autoCorrect='off'
                      spellCheck='false'
                      {...field}
                      onChange={(e) => field.onChange(Number.parseInt(e.target.value, 10) || 0)}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>

          <DialogFooter>
            <Button
              type='submit'
              className='w-full h-12 rounded-lg text-base font-medium hover:shadow-lg hover:shadow-primary/20'
              disabled={mutation.isPending || !form.formState.isDirty}
            >
              {mutation.isPending ? <DotLoader className='size-6!' /> : 'Save Changes'}
            </Button>
          </DialogFooter>
        </form>
      </Form>
    </div>
  );
}
